SELECT 'bof-team-offer-v2',facts || '{"company_location":"Louisville-based business serving customers nationwide","team_offer":"Owner-approved personalized 25% off sitewide for the recipient, their team and other locations. Unlimited repeat uses, no expiration. Use only the server-issued company code; no stacking with other promotions.","outreach_voice":"Authentic, friendly and company-specific. We are getting the word out and offering the team a reason to try us. For verified Louisville-area accounts, naturally mention that we are Louisville-based. Highlight 24-hour production and qualifying free next-day air for vinyl banners without extending these timing claims to every product.","exceptions":"The standing 25% team offer is approved. Other discounts, custom pricing, credit terms, contracts, refunds and capacity commitments require owner approval."}'::jsonb,'owner instruction 2026-10-21'
FROM daniel_sales.knowledge WHERE version='bof-v1' ON CONFLICT DO NOTHING;
